import Image from "next/image";

// Brand logo built from the approved artwork (Option 1 + Favicon 1).
// Assets are generated by scripts/brand-assets.mjs into /public/brand.

/** Compact horizontal lockup: favicon emblem + "EcoSoul / Uttarakhand Travel" wordmark. */
// Loads eagerly (headers, admin bars) but is never preloaded, so it doesn't compete with the hero image.
// `lazy`: below-the-fold placements such as the footer.
export function Logo({ light = false, size = "md", lazy = false }: { light?: boolean; size?: "sm" | "md"; lazy?: boolean }) {
  const h = size === "sm" ? 34 : 42;
  const loading = lazy ? "lazy" : "eager";
  return (
    <span className="flex items-center gap-2.5">
      <Image src="/brand/emblem.png" alt="" width={h} height={h} loading={loading} className="rounded-[22%] shadow-sm ring-1 ring-black/5" />
      <Image
        src={light ? "/brand/wordmark-light.png" : "/brand/wordmark.png"}
        alt="EcoSoul Uttarakhand Travel"
        width={Math.round(h * 0.95 * (495 / 152))}
        height={Math.round(h * 0.95)}
        loading={loading}
      />
    </span>
  );
}

/** Full illustrated logo (Option 1) — use on light backgrounds only. */
export function FullLogo({ width = 260, className = "", preload = false }: { width?: number; className?: string; preload?: boolean }) {
  return (
    <Image
      src="/brand/logo-full.png"
      alt="EcoSoul Uttarakhand Travel — Devbhoomi, Uttarakhand"
      width={width}
      height={Math.round(width * (478 / 588))}
      preload={preload}
      className={className}
    />
  );
}
